package io.github.diodeme.ji.workspace.local;

import static org.junit.jupiter.api.Assertions.assertEquals;

import io.github.diodeme.ji.ai.CancellationToken;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class WorkspaceToolsTest {
    @TempDir Path temporary;

    @Test
    void builtInsPreservePiReadWriteAndExactEditResults() throws Exception {
        try (var workspace = new LocalWorkspaceProvider("workspace-1", temporary)) {
            var write = WorkspaceTools.write(workspace);
            var written = write.executor().execute(Map.of("path", "nested/file.txt", "content", "alpha\nbeta\n",
                    "expectedRevision", 0), CancellationToken.NONE);
            assertEquals("Successfully wrote 11 bytes to nested/file.txt", written.text());
            assertEquals(1L, written.details().get("revision"));

            var read = WorkspaceTools.read(workspace).executor().execute(
                    Map.of("path", "nested/file.txt", "offset", 2, "limit", 1), CancellationToken.NONE);
            assertEquals("beta", read.text());

            var edit = WorkspaceTools.edit(workspace).executor().execute(Map.of(
                    "path", "nested/file.txt", "expectedRevision", 1,
                    "edits", List.of(Map.of("oldText", "alpha", "newText", "ALPHA"))), CancellationToken.NONE);
            assertEquals("Successfully replaced 1 block(s) in nested/file.txt.", edit.text());
            assertEquals("ALPHA\nbeta\n", Files.readString(temporary.resolve("nested/file.txt")));
        }
    }
}
